    next_sick_1 := []: ℤ[];
    next_sick_2 := []: ℤ[];
    next_sick_h := []: 𝔹[];
    // sick(X,T) :- person(X), cold(T).
    for k17 in [0..person_h.length) {
      X := person_1[k17];
      x18 := person_h[k17];
      for k19 in [0..cold_h.length) {
        T := cold_1[k19];
        x20 := cold_h[k19];
        v21 := x18 && x20;
        f22 := false;
        for k23 in [0..next_sick_h.length) {
          if next_sick_1[k23] == X && next_sick_2[k23] == T { next_sick_h[k23] = next_sick_h[k23] || v21; f22 = true; }
        }
        if !f22 { next_sick_1 = next_sick_1 ~ [X]; next_sick_2 = next_sick_2 ~ [T]; next_sick_h = next_sick_h ~ [v21]; }
      }
    }
    // sick(X,T) :- friend(X,Y), sick(Y,T).
    for k24 in [0..friend_h.length) {
      X := friend_1[k24];
      Y := friend_2[k24];
      x25 := friend_h[k24];
      for k26 in [0..sick_h.length) {
        if sick_1[k26] == Y {
          T := sick_2[k26];
          x27 := sick_h[k26];
          v28 := x25 && x27;
          f29 := false;
          for k30 in [0..next_sick_h.length) {
            if next_sick_1[k30] == X && next_sick_2[k30] == T { next_sick_h[k30] = next_sick_h[k30] || v28; f29 = true; }
          }
          if !f29 { next_sick_1 = next_sick_1 ~ [X]; next_sick_2 = next_sick_2 ~ [T]; next_sick_h = next_sick_h ~ [v28]; }
        }
      }
    }
    // sick(X,T) :- next(T0,T), sick(X,T0), stay_sick(X,T).
    for k31 in [0..next_h.length) {
      T0 := next_1[k31];
      T := next_2[k31];
      x32 := next_h[k31];
      for k33 in [0..sick_h.length) {
        if sick_2[k33] == T0 {
          X := sick_1[k33];
          x34 := sick_h[k33];
          for k35 in [0..stay_sick_h.length) {
            if stay_sick_1[k35] == X && stay_sick_2[k35] == T {
              x36 := stay_sick_h[k35];
              v37 := x32 && x34 && x36;
              f38 := false;
              for k39 in [0..next_sick_h.length) {
                if next_sick_1[k39] == X && next_sick_2[k39] == T { next_sick_h[k39] = next_sick_h[k39] || v37; f38 = true; }
              }
              if !f38 { next_sick_1 = next_sick_1 ~ [X]; next_sick_2 = next_sick_2 ~ [T]; next_sick_h = next_sick_h ~ [v37]; }
            }
          }
        }
      }
    }
    sick_1 = next_sick_1;
    sick_2 = next_sick_2;
    sick_h = next_sick_h;
    stage15 = stage15 + 1;
  }

  q40 := false;
  for q40_k in [0..sick_h.length) { if sick_1[q40_k] == 1000000 && sick_2[q40_k] == 9 { q40 = sick_h[q40_k]; } }
