// sickness10_10.pl: a ProbLog program written in WebPPL by tddlog's
// scripts/problog2ppl.py, first order as it is written. A relation is an
// object from a tuple's key to {t: the tuple, v: whether it holds}, v a
// function of no arguments that says whether the tuple holds in the world
// being enumerated, memoized within it; each probabilistic fact is a coin of
// its own (`flip`), drawn where a world first reads it; a rule's instances
// are maps over the relations its body joins. The facts are lpFacts, which
// the runner reads from the facts file: {relation: [[argument ...,
// probability], ...]}. The queries are enumerated exactly, given the
// evidence.

var yes = function() { return true; };
var no = function() { return false; };
// a coin of probability p, drawn once in a world
var coin = function(p) { return mem(function() { return flip(p); }); };
var and = function(xs) { return function() { return all(function(x) { return x(); }, xs); }; };
var not = function(x) { return function() { return !x(); }; };
var keyOf = function(t) { return JSON.stringify(t); };
// whether the tuple t of r holds
var holds = function(r, t) { var e = r[keyOf(t)]; return e ? e.v : no; };
// the entry of t, if it is a tuple of r: none or one to map over
var probe = function(r, t) { var e = r[keyOf(t)]; return e ? [e] : []; };
// the entries of r by their values at positions ps (from 0)
var index = function(r, ps) {
  return _.groupBy(map(function(e) { return {k: keyOf(_.at(e.t, ps)), t: e.t, v: e.v}; }, _.values(r)), 'k');
};
// whether a tuple of the index's key k holds
var holdsAny = function(ix, k) {
  var es = ix[keyOf(k)] || [];
  return function() { return any(function(e) { return e.v(); }, es); };
};
// the choice of an annotated disjunction p1::h1; ...; pn::hn: whether each
// head is the one chosen, the k-th with probability pk and none with the rest
var choose = function(ps) {
  var rest = 1 - sum(ps);
  var vs = _.range(ps.length + (rest > 0 ? 1 : 0));
  var c = mem(function() { return categorical({ps: rest > 0 ? ps.concat([rest]) : ps, vs: vs}); });
  return map(function(k) { return function() { return c() === k; }; }, _.range(ps.length));
};
// the instances, [relation, tuple, holding] each, of relation `name`
var only = function(name, instances) { return filter(function(i) { return i[0] === name; }, instances); };
// the relation of base and instances: a tuple holds where its fact or one
// of its instances does
var relation = function(base, instances) {
  var entries = map(function(e) { return {k: keyOf(e.t), t: e.t, v: e.v}; }, _.values(base)).concat(
    map(function(i) { return {k: keyOf(i[1]), t: i[1], v: i[2]}; }, instances));
  return mapObject(function(k, es) {
    var vs = map(function(e) { return e.v; }, es);
    return {t: es[0].t, v: mem(function() { return any(function(x) { return x(); }, vs); })};
  }, _.groupBy(entries, 'k'));
};
// a relation of facts, [argument ..., probability] each
var relationOfFacts = function(rows) {
  return _.fromPairs(map(function(row) {
    var t = row.slice(0, row.length - 1), p = row[row.length - 1];
    return [keyOf(t), {t: t, v: p >= 1 ? yes : coin(p)}];
  }, rows));
};

var person_facts = relationOfFacts(lpFacts['person/1'] || []);
var friend_facts = relationOfFacts(lpFacts['friend/2'] || []);
var time_facts = relationOfFacts(lpFacts['time/1'] || []);
var next_facts = relationOfFacts(lpFacts['next/2'] || []);

var time = time_facts;

var instances_cold = [].concat(
  // 0.2::cold(T) :- time(T).
  (function() {
    return _.flatten(map(function(e1) {
      var T = e1.t[0];
      return [['cold', [T], and([e1.v, coin(0.2)])]];
    }, _.values(time)));
  })()
);
var cold = relation({}, instances_cold);

var friend = friend_facts;

var next = next_facts;

var person = person_facts;

var instances_stay_sick = [].concat(
  // 0.4::stay_sick(X,T) :- person(X), time(T).
  (function() {
    return _.flatten(map(function(e1) {
      var X = e1.t[0];
      return _.flatten(map(function(e2) {
        var T = e2.t[0];
        return [['stay_sick', [X, T], and([e1.v, e2.v, coin(0.4)])]];
      }, _.values(time)));
    }, _.values(person)));
  })()
);
var stay_sick = relation({}, instances_stay_sick);

// sick/2: recursive; the rules applied in stages from no tuple, each
// reading the stage before, until a stage adds no tuple and the stages number the tuples
var stage_sick = function(rels) {
  var sick = rels[0];
  var sick_by_1 = index(sick, [0]);
  var sick_by_2 = index(sick, [1]);
  var instances_sick = [].concat(
    // sick(X,T) :- person(X), cold(T).
    (function() {
      return _.flatten(map(function(e1) {
        var X = e1.t[0];
        return _.flatten(map(function(e2) {
          var T = e2.t[0];
          return [['sick', [X, T], and([e1.v, e2.v])]];
        }, _.values(cold)));
      }, _.values(person)));
    })(),
    // sick(X,T) :- friend(X,Y), sick(Y,T).
    (function() {
      return _.flatten(map(function(e1) {
        var X = e1.t[0];
        var Y = e1.t[1];
        return _.flatten(map(function(e2) {
          var T = e2.t[1];
          return [['sick', [X, T], and([e1.v, e2.v])]];
        }, (sick_by_1[keyOf([Y])] || [])));
      }, _.values(friend)));
    })(),
    // sick(X,T) :- next(T0,T), sick(X,T0), stay_sick(X,T).
    (function() {
      return _.flatten(map(function(e1) {
        var T0 = e1.t[0];
        var T = e1.t[1];
        return _.flatten(map(function(e2) {
          var X = e2.t[0];
          return _.flatten(map(function(e3) {
            return [['sick', [X, T], and([e1.v, e2.v, e3.v])]];
          }, probe(stay_sick, [X, T])));
        }, (sick_by_2[keyOf([T0])] || [])));
      }, _.values(next)));
    })()
  );
  var next_sick = relation({}, instances_sick);
  return [next_sick];
};
var stages_sick = function(rels, stage, before) {
  var size = sum(map(function(r) { return _.size(r); }, rels));
  return stage < size || size !== before ? stages_sick(stage_sick(rels), stage + 1, size) : rels;
};
var rels_sick = stages_sick([{}], 0, -1);
var sick = rels_sick[0];

// component 0 bool
// component 1 bool
// component 2 bool
// component 3 bool
// component 4 bool
// component 5 bool
// component 6 bool
// component 7 bool
// component 8 bool
// component 9 bool
var model = function() {
  condition(!holds(sick, ['p1', 0])());
  condition(!holds(sick, ['p4', 0])());
  condition(!holds(sick, ['p5', 0])());
  condition(!holds(sick, ['p6', 0])());
  condition(!holds(sick, ['p8', 0])());
  condition(!holds(sick, ['p2', 1])());
  condition(!holds(sick, ['p6', 1])());
  condition(!holds(sick, ['p0', 2])());
  condition(!holds(sick, ['p2', 2])());
  condition(!holds(sick, ['p3', 2])());
  condition(!holds(sick, ['p6', 2])());
  condition(!holds(sick, ['p8', 2])());
  condition(!holds(sick, ['p2', 3])());
  condition(!holds(sick, ['p3', 3])());
  condition(!holds(sick, ['p5', 3])());
  condition(!holds(sick, ['p9', 3])());
  condition(!holds(sick, ['p6', 4])());
  condition(!holds(sick, ['p9', 4])());
  condition(holds(sick, ['p0', 5])());
  condition(holds(sick, ['p2', 5])());
  condition(holds(sick, ['p4', 5])());
  condition(holds(sick, ['p7', 5])());
  condition(holds(sick, ['p8', 5])());
  condition(holds(sick, ['p9', 5])());
  condition(holds(sick, ['p3', 6])());
  condition(holds(sick, ['p2', 7])());
  condition(holds(sick, ['p4', 7])());
  condition(holds(sick, ['p5', 7])());
  condition(!holds(sick, ['p7', 7])());
  condition(holds(sick, ['p3', 8])());
  condition(holds(sick, ['p8', 8])());
  return [holds(sick, ['p0', 9])(),
          holds(sick, ['p1', 9])(),
          holds(sick, ['p2', 9])(),
          holds(sick, ['p3', 9])(),
          holds(sick, ['p4', 9])(),
          holds(sick, ['p5', 9])(),
          holds(sick, ['p6', 9])(),
          holds(sick, ['p7', 9])(),
          holds(sick, ['p8', 9])(),
          holds(sick, ['p9', 9])()];
};
Infer({method: 'enumerate'}, model);

