    }
    sick_1 = next_sick_1;
    sick_2 = next_sick_2;
    sick_h = next_sick_h;
    stage15 = stage15 + 1;
  }

  q40 := false;
  for q40_k in [0..sick_h.length) { if sick_1[q40_k] == 1000000 && sick_2[q40_k] == 9 { q40 = sick_h[q40_k]; } }
  q41 := false;
