  for i in [0..person_facts_p.length) { if person_facts_p[i] < 1 { person_facts_h[i] = flip(person_facts_p[i]); } else { person_facts_h[i] = true; } }
  // friend/2: 25 facts
  friend_facts_1 := [1000000, 1000000, 1000000, 1000001, 1000001, 1000001, 1000001, 1000001, 1000006, 1000006, 1000006, 1000007, 1000007, 1000008, 1000009, 1000010, 1000010, 1000011, 1000011, 1000012, 1000002, 1000002, 1000004, 1000005, 1000005]: ℤ[];
