    for k9 in [0..time_h.length) {
      T := time_1[k9];
      x10 := time_h[k9];
      c11 := flip(0.4);
      v12 := x8 && x10 && c11;
      f13 := false;
      for k14 in [0..stay_sick_h.length) {
        if stay_sick_1[k14] == X && stay_sick_2[k14] == T { stay_sick_h[k14] = stay_sick_h[k14] || v12; f13 = true; }
